<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { CheckCircle2, Circle, CircleDot, CircleHelp, XCircle } from '@lucide/svelte'; import { cn } from '../../utils.js'; import { useTestContext } from './context.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLSpanElement>, 'children' | 'class'> { class?: string; children?: Snippet; } let { class: className = '', children, ...rest }: Props = $props(); const test = useTestContext('TestStatus');</script>
<span {...rest} class={cn('svadmin-ai-tests-part__test-status', `svadmin-ai-tests-part__test-status--${test.status}`, className)} data-slot="test-status" aria-label={test.status}>{#if children}{@render children()}{:else}{#if test.status === 'passed'}<CheckCircle2 size={14} aria-hidden="true" />{:else if test.status === 'failed'}<XCircle size={14} aria-hidden="true" />{:else if test.status === 'running'}<CircleDot size={14} aria-hidden="true" />{:else if test.status === 'todo'}<CircleHelp size={14} aria-hidden="true" />{:else}<Circle size={14} aria-hidden="true" />{/if}{/if}</span>
<style>.svadmin-ai-tests-part__test-status { display: inline-flex; color: var(--muted-foreground, currentColor); }.svadmin-ai-tests-part__test-status--passed { color: var(--success, currentColor); }.svadmin-ai-tests-part__test-status--failed { color: var(--destructive, currentColor); }.svadmin-ai-tests-part__test-status--running { color: var(--primary, currentColor); }</style>
